function solve(products, searchWord) {
  const res = [];
  let prefix = '';
  for (let i = 0; i < searchWord.length; i++) {
    prefix += searchWord[i];
    const matches = [];
    for (let j = 0; j < products.length; j++) {
      const p = products[j];
      if (p.length >= prefix.length && p.slice(0, prefix.length) === prefix) {
        matches.push(p);
      }
    }
    matches.sort(function (a, b) { return a < b ? -1 : a > b ? 1 : 0; });
    res.push(matches.slice(0, 3));
  }
  return res;
}

function solve(products, searchWord) {
  const sorted = products.slice().sort(function (a, b) { return a < b ? -1 : a > b ? 1 : 0; });
  const res = [];
  let prefix = '';
  for (let i = 0; i < searchWord.length; i++) {
    prefix += searchWord[i];
    let lo = 0;
    let hi = sorted.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (sorted[mid] < prefix) lo = mid + 1;
      else hi = mid;
    }
    const bucket = [];
    for (let idx = lo; idx < sorted.length && bucket.length < 3; idx++) {
      const p = sorted[idx];
      if (p.length < prefix.length || p.slice(0, prefix.length) !== prefix) break;
      bucket.push(p);
    }
    res.push(bucket);
  }
  return res;
}
